\set ON_ERROR_STOP on
begin;
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAILED: %',label; end if; raise notice 'PASS: %',label; end $$;
grant execute on function pg_temp.assert(boolean,text) to authenticated;
insert into public.employee_directory(email,full_name,legal_entity) values ('fulfill-admin@example.test','Fulfillment admin','Admin LLC'),('fulfill-user@example.test','Directory Recipient','Recipient LLC');
insert into auth.users(id,email) values ('00000000-0000-0000-0000-000000000071','fulfill-admin@example.test'),('00000000-0000-0000-0000-000000000072','fulfill-user@example.test');
update public.employees set is_admin=true where email='fulfill-admin@example.test';
insert into public.shop_admins(email,unit_id) select lower(email),'10000000-0000-4000-8000-000000000002'::uuid from public.employees where is_admin on conflict do nothing;
update public.employees set full_name='Outdated profile name' where email='fulfill-user@example.test';
insert into public.pickup_offices(id,name,address) values ('60000000-0000-0000-0000-000000000071','Test office','Tashkent Test street');
insert into public.products(id,name) values ('10000000-0000-0000-0000-000000000071','Fulfillment shirt');
insert into public.product_variants(id,product_id,sku) values ('20000000-0000-0000-0000-000000000071','10000000-0000-0000-0000-000000000071','FULFILL-SHIRT');
insert into public.stock_movements(variant_id,movement_type,qty) values ('20000000-0000-0000-0000-000000000071','income',20);
update public.merch_settings set pickup_message='Custom pickup time and place' where id=1;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000072',true);
select public.create_merch_order_v2('[{"variant_id":"20000000-0000-0000-0000-000000000071","qty":1}]','office','60000000-0000-0000-0000-000000000071','+998901234567','ignored','ignored','must not be stored',null,null);
select pg_temp.assert((select full_name='Directory Recipient' and legal_entity='Recipient LLC' and comment is null and not is_remote and pickup_code ~ '^[0-9]{20}$' and pickup_office_name='Test office' and pickup_office_address='Tashkent Test street' from public.orders where fulfillment_mode='office'),'office checkout snapshots directory identity and office, discards comment, issues Code128 identifier');
select pg_temp.assert(public.my_checkout_identity()->>'legal_entity'='Recipient LLC','own legal entity retrieved without exposing the directory');
select public.create_merch_order_v2('[{"variant_id":"20000000-0000-0000-0000-000000000071","qty":1}]','remote_shipping',null,'+998901234567','Kazakhstan','Almaty','Optional note',null,null);
select pg_temp.assert((select is_remote and pickup_code is null and country='Kazakhstan' and city='Almaty' and comment='Optional note' and remote_contact_name='Fulfillment admin' from public.orders where fulfillment_mode='remote_shipping'),'remote shipment keeps city, country and optional comment and has no pickup code');
select public.create_merch_order_v2('[{"variant_id":"20000000-0000-0000-0000-000000000071","qty":1}]','remote_visit','60000000-0000-0000-0000-000000000071','+998901234567',null,null,'Visit note',(now() at time zone 'Asia/Tashkent')::date+3,(now() at time zone 'Asia/Tashkent')::date+6);
select pg_temp.assert((select not is_remote and pickup_code is not null and visit_until=visit_from+3 from public.orders where fulfillment_mode='remote_visit') and not exists(select 1 from public.order_tasks),'visiting employee gets a barcode while admin tasks remain private');
do $$ begin
 begin insert into public.pickup_offices(name) values ('Unauthorized office'); raise exception 'MISSING_DENIAL'; exception when insufficient_privilege then null; end;
 begin perform public.admin_contact_visit('60000000-0000-0000-0000-000000000071'); raise exception 'MISSING_DENIAL'; exception when others then if sqlerrm<>'not_admin' then raise; end if; end;
 begin perform public.create_merch_order_v2('[{"variant_id":"20000000-0000-0000-0000-000000000071","qty":1}]','remote_shipping',null,'123',null,null,null,null,null); raise exception 'MISSING_DENIAL'; exception when others then if sqlerrm not like 'Укажите корректный номер%' then raise; end if; end;
 begin perform public.create_merch_order_v2('[{"variant_id":"20000000-0000-0000-0000-000000000071","qty":1}]','remote_shipping',null,'+998901234567','Kazakhstan',null,null,null,null); raise exception 'MISSING_DENIAL'; exception when others then if sqlerrm<>'Укажите страну и город' then raise; end if; end;
 begin perform public.create_merch_order_v2('[{"variant_id":"20000000-0000-0000-0000-000000000071","qty":1}]','remote_visit','60000000-0000-0000-0000-000000000071','+998901234567',null,null,null,current_date+5,current_date+2); raise exception 'MISSING_DENIAL'; exception when others then if sqlerrm<>'Укажите корректные даты визита в Ташкент' then raise; end if; end;
end $$;
reset role;
select pg_temp.assert((select count(*)=3 from public.orders) and (select reserved_qty=3 from public.product_variants where sku='FULFILL-SHIRT') and (select count(*)=1 from public.order_tasks),'invalid phone, location and visit dates leave no partial order, reserve or task');
select pg_temp.assert((select due_on=(now() at time zone 'Asia/Tashkent')::date+3 and reserve_until=due_on+3 from public.order_tasks),'visit task stores arrival and departure dates in Tashkent calendar');
alter table public.order_events add constraint fail_visit_event check(action<>'visit_reserved') not valid;
set local role authenticated;
do $$ begin
 begin perform public.create_merch_order_v2('[{"variant_id":"20000000-0000-0000-0000-000000000071","qty":1}]','remote_visit','60000000-0000-0000-0000-000000000071','+998901234567',null,null,null,current_date+1,current_date+2); raise exception 'MISSING_DENIAL'; exception when check_violation then null; end;
end $$;
reset role;
select pg_temp.assert((select count(*)=3 from public.orders) and (select reserved_qty=3 from public.product_variants where sku='FULFILL-SHIRT') and (select count(*)=1 from public.order_tasks),'task audit failure rolls back checkout and its stock reservation');
alter table public.order_events drop constraint fail_visit_event;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000071',true);
update public.pickup_offices set name='Renamed office',address='Changed address',is_active=false where id='60000000-0000-0000-0000-000000000071';
select pg_temp.assert((select pickup_office_name='Test office' and pickup_office_address='Tashkent Test street' from public.orders where fulfillment_mode='office'),'office renaming preserves existing order snapshot');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000072',true);
select pg_temp.assert(exists(select 1 from public.pickup_offices where id='60000000-0000-0000-0000-000000000071' and not is_active),'inactive office remains visible but unavailable to recipients');
do $$ begin
 begin perform public.create_merch_order_v2('[{"variant_id":"20000000-0000-0000-0000-000000000071","qty":1}]','office','60000000-0000-0000-0000-000000000071','+998901234567',null,null,null,null,null);raise exception 'MISSING_DENIAL';exception when others then if sqlerrm<>'Выберите действующий офис получения' then raise; end if;end;
end $$;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000071',true);
do $$ begin
 begin perform public.admin_contact_visit((select id from public.order_tasks limit 1));raise exception 'MISSING_DENIAL';exception when others then if sqlerrm<>'Отметить связь можно в день приезда или позже' then raise; end if;end;
end $$;
reset role; update public.order_tasks set due_on=(now() at time zone 'Asia/Tashkent')::date; set local role authenticated;
select public.admin_contact_visit(id) from public.order_tasks;
select public.admin_contact_visit(id) from public.order_tasks;
select pg_temp.assert((select count(*)=1 from public.order_events where action='visit_contacted') and (select contacted_by=auth.uid() from public.order_tasks),'contact acknowledgement is admin-only and repeat-safe');
select public.admin_update_order(id,'ready',null,null) from public.orders where fulfillment_mode='remote_visit';
select public.admin_issue_order(pickup_code) from public.orders where fulfillment_mode='remote_visit';
select pg_temp.assert((select closed_at is not null from public.order_tasks) and (select total_qty=19 and reserved_qty=2 from public.product_variants where sku='FULFILL-SHIRT'),'barcode issuance of visitor closes task and writes off exactly one reserved item');
select public.admin_issue_order(pickup_code) from public.orders where fulfillment_mode='remote_visit';
select pg_temp.assert((select total_qty=19 and reserved_qty=2 from public.product_variants where sku='FULFILL-SHIRT'),'repeat visitor scan does not deduct stock twice');
update public.pickup_offices set is_active=true where id='60000000-0000-0000-0000-000000000071';
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000072',true);
select public.create_merch_order_v2('[{"variant_id":"20000000-0000-0000-0000-000000000071","qty":1}]','remote_visit','60000000-0000-0000-0000-000000000071','+998901234567',null,null,null,current_date+1,current_date+2);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000071',true);
select public.admin_update_order(o.id,'cancelled',null,null) from public.orders o join public.order_tasks t on t.order_id=o.id where t.closed_at is null;
select pg_temp.assert(not exists(select 1 from public.order_tasks where closed_at is null) and (select reserved_qty=2 from public.product_variants where sku='FULFILL-SHIRT'),'visitor cancellation closes reminder and releases its reserve');
select public.admin_import_employees('[{"email":"legal-import@example.test","full_name":"Imported entity","legal_entity":"Import LLC"}]');
select pg_temp.assert((select legal_entity='Import LLC' from public.employee_directory where email='legal-import@example.test'),'bulk import supports optional legal entity');
rollback;
